from __future__ import annotations

import logging
import pathlib
import re
import shutil
from abc import ABCMeta, abstractmethod
from typing import Optional

import attr
from lxml import etree
from taf.sw.wtssim import wtssim  # type: ignore[import-untyped]
from ute_testline_configuration.ute_config import UTE_CONFIG  # type: ignore

from taf.ul.ue.sim.env_setup.devices.simulator import Simulator
from taf.ul.ue.sim.env_setup.utils.egate_utils import execute_wtssim_command, get_cells_from_external_enbs


@attr.s(cmp=False, hash=True)
class IphyAirphoneInterface(Simulator, metaclass=ABCMeta):
    idx = attr.ib(type=int)
    configuration = attr.ib(type=UTE_CONFIG)
    remote_host = attr.ib(type=str)
    output_directory_path = attr.ib(type=str)
    config_type = attr.ib(type="str")
    name = attr.ib(default="", type="str", init=False)
    sim_xml_path = attr.ib(default="", type=str, init=False)
    connected_bts_id = attr.ib(default=1, type=int, init=False)
    _radio_version = attr.ib(default=None, type=Optional[dict], init=False, repr=False, hash=False)

    def __attrs_post_init__(self):
        self.name = type(self).__name__.lower()

    def set_xml_path(self, xml_path: str) -> None:
        orig_path = pathlib.Path(xml_path)
        new_path = pathlib.Path(self.output_directory_path).joinpath(f"MODIFIED_{orig_path.name}")
        shutil.copy(orig_path, new_path)
        self.sim_xml_path = new_path.as_posix()

    @abstractmethod
    def _set_vlan(self): ...

    def _configure(self, bts_targetbd: str | None, skip_restart: bool) -> None:
        if bts_targetbd is not None:
            self._radio_version = self._get_radio_versions_dict(bts_targetbd)
            self._modify_radio_versions()
            self._set_vlan()
        self._upload_config_xml()
        self.logger.info(f"{self.name.capitalize()} {self.lmp_ip} updated. Going to reset ...")
        if not skip_restart:
            self.reset()
        else:
            self.logger.info("Skip simulator reset detected. Reset will not be performed.")

    def _upload_config_xml(self) -> None:
        """Uploads iphy.xml from local_path to given partition of Iphy or AirPhone."""
        self.logger.info(f"Uploading file: {self.sim_xml_path}")
        with self._get_remote_host_ssh() as ssh_connection:
            with self._get_device_ssh(ssh_connection) as device_ssh:
                device_ssh.files.put(self.sim_xml_path, "/ffs/run/simmode/iphy.xml", timeout=30)

    @staticmethod
    def _get_radio_versions_dict(enb_targetbd: str) -> dict[str, str]:
        """
        Returns a dictionary of radio module types (without leading 'LTX_') and their versions extracted from given
        TargetBD file.
        """
        hw_resources = etree.parse(enb_targetbd).findall(".//hwResource")
        ret = {}
        for hwResource in hw_resources:
            if (build_key := hwResource.get("resourceBuildKey")) and (sw_version := hwResource.get("resourceSWVersion")):
                ret[build_key[4:]] = sw_version
        return ret

    @staticmethod
    def _set_radio_versions(config_xml: etree._ElementTree, radio_versions_dict: dict) -> None:
        """Searches through Identity parameter to find RMOD type:
        * resourceBuildKey - it contains exact name of RMOD, but may(?) be missing
        * productname - for OBSAI RMOD type
        * cardName - for CPRI RMOD type
        """
        all_identities = config_xml.findall(".//identity")
        for identity in all_identities:
            rmod_name = IphyAirphoneInterface._get_rmod_name_from_xml(identity)
            version = IphyAirphoneInterface._find_version(radio_versions_dict, rmod_name)
            assert version is not None, (
                "Unable to find RRH name via `resourceBuildKey` or `productname` or `cardName`." "Check iphy.xml if data is correct."
            )
            if (build_version := identity.find("buildversion")) is not None and identity.findtext("buildversion"):
                build_version.text = version
            if (build_name := identity.find("buildname")) is not None and identity.findtext("buildname"):
                build_name.text = version
            if (bld_version := identity.find("bldVersion")) is not None and identity.findtext("bldVersion"):
                bld_version.text = version

    @staticmethod
    def _get_rmod_name_from_xml(identity: etree._Element) -> str:
        rmod_name = identity.findtext("resourceBuildKey") or identity.findtext("productname") or identity.findtext("cardName")
        assert rmod_name is not None, "rmod_name not found"
        rmod_name = rmod_name.lstrip("LTX_")
        return rmod_name

    def _modify_radio_versions(self) -> None:
        if self._radio_version:
            with self.open_rmods_xml(self.sim_xml_path) as xml:
                self._set_radio_versions(xml, self._radio_version)

    @staticmethod
    def _find_version(radio_versions_dict: dict, radio_type: str) -> Optional[str]:
        if radio_type in radio_versions_dict:
            return radio_versions_dict[radio_type]
        elif radio_type + "_N1" in radio_versions_dict:
            return radio_versions_dict[radio_type + "_N1"]
        elif radio_type + "_E1" in radio_versions_dict:
            return radio_versions_dict[radio_type + "_E1"]
        return None


def ensure_sibs_are_received_on_each_cell_with_iphy_or_airphone(wtssim: wtssim, alias: str, logger: logging.Logger) -> None:
    SIBS_REGEXP = re.compile(r"(?P<ib>[\w-]*?)\s+(?P<periodicity>\d+)\s+(?P<offset>\d+)\s+(?P<received>\w+)")
    enbs_cells_data = get_cells_from_external_enbs(wtssim, alias, logger)
    for enb_id, cell_data in enbs_cells_data.items():
        for cell_id, cell_params in cell_data.items():
            if cell_id in ("enb", "gnb") or not is_cell_mandatory(cell_params):
                continue
            data = execute_wtssim_command(
                f"enb_cell_ib_disp enb={enb_id} cell={cell_id}",
                wtssim,
                alias,
                logger,
            )
            for match in SIBS_REGEXP.finditer(data):
                received = str(match.group("received")).lower()
                logger.debug("{} - received: {}".format(match.group("ib"), received))
                if received != "yes":
                    raise Exception("{} not received. Attach will not be possible")


def is_cell_mandatory(cell_params):
    return cell_params["mandatory_for_activation"].lower() == "yes"
